use std::collections::BTreeSet;
use std::collections::VecDeque;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;
use std::path::PathBuf;
use std::process::Command;
use std::sync::Mutex;
use std::thread;
use std::time::Instant;

struct TritonKernelSpec {
    artifact_dir: &'static str,
    kernel_path: &'static str,
    kernel_name: &'static str,
    signature: &'static str,
    grid: &'static str,
    out_name: &'static str,
    num_warps: u32,
    num_stages: u32,
}

struct NvccTask {
    cu_file: PathBuf,
    obj_file: PathBuf,
    args: Vec<String>,
}

struct FlashInferIncludes {
    include: PathBuf,
    csrc: PathBuf,
    cutlass: PathBuf,
    cutlass_util: PathBuf,
    spdlog: PathBuf,
    /// Vendored CCCL (cub, libcudacxx, thrust). Must be passed as `-I` while the
    /// CTK include dir is `-isystem`, so these override the toolkit's older CCCL
    /// copy — FlashInfer v0.6+ uses APIs (e.g. `cuda::fast_mod_div`) that older
    /// CTK CCCL lacks. Mirrors upstream flashinfer/jit/cpp_ext.py ordering.
    cccl: Vec<PathBuf>,
}

const GLM52_TRTLLM_FMHA_CUBINS: &[(&str, &str)] = &[
    (
        "kGlm52FmhaSparseSeedQ8",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ8Kv128StaticSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparsePersistentSeedQ8",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1VarSeqQ8Kv128PersistentSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparseShortQ8",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1VarSeqQ8Kv128PersistentSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparseLongQ8",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ8Kv128StaticSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparseLongQ16",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparseLongQ16V256",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta256PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
    ),
    (
        "kGlm52FmhaSparseLongQ16V512",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ16Kv128StaticSwapsAbForGen.cubin",
    ),
];

fn generate_glm52_trtllm_fmha_cubins(root: &Path, out_dir: &Path) {
    let cubin_dir = root.join("cubin/glm52");
    let mut generated = String::from(
        "// Generated by pegainfer-kernels/build.rs from the checked-in FlashInfer cubins.\n\
         #pragma once\n\n",
    );
    for &(symbol, file_name) in GLM52_TRTLLM_FMHA_CUBINS {
        let path = cubin_dir.join(file_name);
        println!("cargo:rerun-if-changed={}", path.display());
        let bytes = fs::read(&path).unwrap_or_else(|err| {
            panic!(
                "failed to read GLM5.2 TRTLLM FMHA cubin {}: {err}",
                path.display()
            )
        });
        writeln!(&mut generated, "static const unsigned char {symbol}[] = {{")
            .expect("write cubin array declaration");
        for chunk in bytes.chunks(16) {
            generated.push_str("  ");
            for byte in chunk {
                write!(&mut generated, "0x{byte:02x}, ").expect("write cubin byte");
            }
            generated.push('\n');
        }
        generated.push_str("};\n");
        writeln!(
            &mut generated,
            "static constexpr unsigned int {symbol}Size = sizeof({symbol});\n"
        )
        .expect("write cubin array size");
    }
    let output = out_dir.join("glm52_trtllm_fmha_cubins.inc");
    fs::write(&output, generated).unwrap_or_else(|err| {
        panic!(
            "failed to write generated GLM5.2 TRTLLM FMHA cubin header {}: {err}",
            output.display()
        )
    });
}

fn workspace_root() -> PathBuf {
    crate_root().join("..")
}

/// AOT-export the CuTe DSL tcgen05 fp8 GEMMs and compile the dispatch shim
/// around them (csrc/glm52/glm52_fp8_dsl_gemm.c). Opt-in via
/// `PEGAINFER_CUTEDSL_PYTHON` (a Python with torch + nvidia-cutlass-dsl on a
/// CUDA box); without it the shim compiles as an empty-table stub and the
/// runtime stays on the CUTLASS route. The exported objects resolve their
/// `_cuda*` wrapper symbols from the DSL wheel's libcute_dsl_runtime.so —
/// linked here, needed on LD_LIBRARY_PATH at run time.
fn build_glm52_cutedsl_fp8_dsl(root: &Path, out_dir: &Path, cuda_include: &Path) {
    println!("cargo:rerun-if-env-changed=PEGAINFER_CUTEDSL_PYTHON");
    let shim_c = root.join("csrc/glm52/glm52_fp8_dsl_gemm.c");
    println!("cargo:rerun-if-changed={}", shim_c.display());
    let mut shim = cc::Build::new();
    shim.include(cuda_include)
        .flag("-std=c11")
        .warnings(false)
        .file(&shim_c);
    if let Ok(python) = std::env::var("PEGAINFER_CUTEDSL_PYTHON") {
        let script = root.join("tools/cutedsl/export_glm52_fp8_dsl.py");
        let benches = workspace_root().join("pegainfer-glm52/benches");
        let gen_dir = out_dir.join("cutedsl_fp8_dsl");
        fs::create_dir_all(&gen_dir).expect("create the cutedsl gen dir");
        println!("cargo:rerun-if-changed={}", script.display());
        for source in [
            "kernel_lab/units/fp8_gemm_dsl_tc_kernel.py",
            "kernel_lab/units/fp8_gemm_dsl_tc.py",
        ] {
            println!("cargo:rerun-if-changed={}", benches.join(source).display());
        }
        let status = time_phase("cutedsl fp8 GEMM export", || {
            Command::new(&python)
                .arg(&script)
                .arg("--benches-dir")
                .arg(&benches)
                .arg("--out-dir")

