267	fn time_phase<T>(label: impl AsRef<str>, f: impl FnOnce() -> T) -> T {
268	    if !build_timing_enabled() {
269	        return f();
270	    }
271	
272	    let started = Instant::now();
273	    let result = f();
274	    println!(
275	        "cargo:warning=build-timing {} {:.3}s",
276	        label.as_ref(),
277	        started.elapsed().as_secs_f64()
278	    );
279	    result
280	}
