282	fn parse_job_count_env(name: &str) -> Option<usize> {
283	    let value = std::env::var(name).ok()?;
284	    match value.trim().parse::<usize>() {
285	        Ok(jobs) if jobs > 0 => Some(jobs),
286	        _ => {
287	            println!("cargo:warning=Ignoring invalid {name}={value}; expected a positive integer.");
288	            None
289	        }
290	    }
291	}
