293	fn nvcc_job_count() -> usize {
294	    if let Some(jobs) = parse_job_count_env("PEGAINFER_NVCC_JOBS") {
295	        return jobs;
296	    }
297	
298	    parse_job_count_env("NUM_JOBS")
299	        .or_else(|| thread::available_parallelism().ok().map(usize::from))
300	        .unwrap_or(1)
301	        .max(1)
