304	fn nvcc_task_priority(cu_file: &Path) -> usize {
305	    match cu_file.file_stem().and_then(|stem| stem.to_str()) {
306	        Some("paged_attention") => 0,
307	        Some(
308	            "paged_attention_hd512"
309	            | "paged_attention_hd256"
310	            | "paged_attention_window_hd256"
311	            | "flashinfer_sampling",
312	        ) => 1,
313	        Some("flashinfer_top1") => 2,
314	        Some("flashinfer_norm") => 3,
315	        _ => 10,
316	    }
