355	fn nvcc_command(nvcc: &str) -> Command {
356	    println!("cargo:rerun-if-env-changed=PEGAINFER_NVCC_LAUNCHER");
357	    match std::env::var_os("PEGAINFER_NVCC_LAUNCHER").filter(|value| !value.is_empty()) {
358	        Some(launcher) => {
359	            let mut command = Command::new(launcher);
360	            command.arg(nvcc);
361	            command
362	        }
363	        None => Command::new(nvcc),
364	    }
365	}
