367	fn nvcc_supported_arches(nvcc: &str) -> Option<BTreeSet<String>> {
368	    let output = nvcc_command(nvcc).arg("--list-gpu-arch").output().ok()?;
369	    if !output.status.success() {
370	        return None;
371	    }
372	
373	    Some(
374	        String::from_utf8_lossy(&output.stdout)
375	            .lines()
376	            .map(str::trim)
377	            .filter(|line| line.starts_with("compute_"))
378	            .map(str::to_string)
379	            .collect(),
380	    )
