383	fn normalize_nvcc_sm(sm: &str, supported_arches: Option<&BTreeSet<String>>) -> String {
384	    let preferred = match sm {
385	        "120" | "120f" => Some("120f"),
386	        "121" | "121a" => Some("121a"),
387	        _ => None,
388	    };
389	    if let Some(preferred) = preferred {
390	        if supported_arches.is_some_and(|arches| arches.contains(&format!("compute_{preferred}"))) {
391	            return preferred.to_string();
392	        }
393	        let raw = sm_numeric_prefix(sm).map_or_else(|| sm.to_string(), |sm| sm.to_string());
394	        println!(
395	            "cargo:warning=nvcc does not list compute_{preferred}; compiling CUDA kernels for raw sm_{raw}"
396	        );
397	        return raw;
398	    }
399	    sm.to_string()
400	}
