410	fn sm_targets_from_nvidia_smi() -> Option<Vec<String>> {
411	    let output = Command::new("nvidia-smi")
412	        .args(["--query-gpu=compute_cap", "--format=csv,noheader"])
413	        .output()
414	        .ok()?;
415	    if !output.status.success() {
416	        return None;
417	    }
418	
419	    let stdout = String::from_utf8_lossy(&output.stdout);
420	    let mut sms = BTreeSet::new();
421	    for line in stdout.lines() {
422	        let cap = line.split(',').next().unwrap_or(line).trim();
423	        if let Some(sm) = parse_sm_token(cap) {
424	            sms.insert(sm);
425	        }
426	    }
427	
428	    if sms.is_empty() {
429	        None
430	    } else {
431	        Some(sms.into_iter().collect())
432	    }
433	}
