435	fn detect_sm_targets() -> Vec<String> {
436	    if let Ok(env) = std::env::var("PEGAINFER_CUDA_SM").or_else(|_| std::env::var("CUDA_SM")) {
437	        let mut sms = Vec::new();
438	        for token in env.split(',') {
439	            if let Some(sm) = parse_sm_token(token) {
440	                sms.push(sm);
441	            } else {
442	                print!(
443	                    "cargo:warning=Invalid SM token '{}' in CUDA_SM environment variable, skipping.",
444	                    token
445	                );
446	            }
447	        }
448	        if !sms.is_empty() {
449	            return sms;
450	        }
451	        print!(
452	            "cargo:warning=No valid SM tokens found in CUDA_SM environment variable '{}', falling back to auto-detection.",
453	            env
454	        );
455	    }
456	
457	    if let Some(sms) = sm_targets_from_nvidia_smi() {
458	        return sms;
459	    }
460	
461	    print!(
462	        "cargo:warning=Failed to detect GPU SMs via nvidia-smi. Set PEGAINFER_CUDA_SM/CUDA_SM environment variable to override."
463	    );
464	    panic!("GPU detection failed");
465	}
