467	fn nvcc_arch_args(normalized_sms: &[String]) -> Vec<String> {
468	    let mut args = Vec::new();
469	    for sm in normalized_sms {
470	        args.push("-gencode".to_string());
471	        args.push(format!("arch=compute_{sm},code=sm_{sm}"));
472	    }
473	
474	    if let Some(max_sm) = normalized_sms
475	        .iter()
476	        .max_by_key(|sm| sm_numeric_prefix(sm).unwrap_or(0))
477	    {
478	        args.push("-gencode".to_string());
479	        args.push(format!("arch=compute_{max_sm},code=compute_{max_sm}"));
480	    }
481	
482	    args
483	}
