485	fn nvcc_accepts_gencode(nvcc: &str, compute: &str, sm: &str) -> bool {
486	    let stem = format!(
487	        "pegainfer_nvcc_probe_{}_compute_{compute}_sm_{sm}",
488	        std::process::id()
489	    );
490	    let cu_path = std::env::temp_dir().join(format!("{stem}.cu"));
491	    let obj_path = std::env::temp_dir().join(format!("{stem}.o"));
492	    if let Err(err) = fs::write(
493	        &cu_path,
494	        "extern \"C\" __global__ void pegainfer_nvcc_probe() {}\n",
495	    ) {
496	        println!(
497	            "cargo:warning=Failed to write nvcc probe {}: {err}",
498	            cu_path.display()
499	        );
500	        return false;
501	    }
502	
503	    let output = nvcc_command(nvcc)
504	        .args(["-c"])
505	        .arg(&cu_path)
506	        .arg("-o")
507	        .arg(&obj_path)
508	        .arg("-gencode")
509	        .arg(format!("arch=compute_{compute},code=sm_{sm}"))
510	        .output();
511	    let _ = fs::remove_file(&cu_path);
512	    let _ = fs::remove_file(&obj_path);
513	
514	    match output {
515	        Ok(output) if output.status.success() => true,
516	        Ok(output) => {
517	            println!(
518	                "cargo:warning=nvcc rejected compute_{compute}/sm_{sm} probe: {}",
519	                String::from_utf8_lossy(&output.stderr).trim()
520	            );
521	            false
522	        }
523	        Err(err) => {
524	            println!("cargo:warning=Failed to run nvcc arch probe: {err}");
525	            false
526	        }
