319	fn parse_sm_token(raw: &str) -> Option<String> {
320	    let token = raw.trim().trim_matches('"');
321	    if token.is_empty() {
322	        return None;
323	    }
324	
325	    let token = token
326	        .strip_prefix("sm_")
327	        .or_else(|| token.strip_prefix("compute_"))
328	        .unwrap_or(token);
329	
330	    if let Some((major, minor)) = token.split_once('.') {
331	        let digit_count = minor.chars().take_while(char::is_ascii_digit).count();
332	        let (minor_digits, suffix) = minor.split_at(digit_count);
333	        if major.chars().all(|c| c.is_ascii_digit())
334	            && !minor_digits.is_empty()
335	            && suffix.chars().all(|c| c.is_ascii_alphabetic())
336	        {
337	            return Some(format!("{major}{minor_digits}{suffix}"));
338	        }
339	        return None;
340	    }
341	
342	    let digit_count = token.chars().take_while(char::is_ascii_digit).count();
343	    let (digits, suffix) = token.split_at(digit_count);
344	    if !digits.is_empty() && suffix.chars().all(|c| c.is_ascii_alphabetic()) {
345	        if digits.len() == 1 {
346	            return Some(format!("{digits}0{suffix}"));
347	        }
348	        return Some(format!("{digits}{suffix}"));
349	    }
350	
351	    None
352	}
